window.NPC_CHUNK_58 = [{"name":"Conna The Wise","cr":12,"xp":19200,"race":"stone giant","gender":"Female","age_category":"elder","classes":[{"class":"sorcerer","level":6}],"alignment":"N","size":"Large","type":"humanoid","sub_types":["giant"],"init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":29,"ac_touch":14,"ac_flat_footed":26,"ac_mods":"+4 armor, +2 deflection, +2 Dex, +1 dodge, +11 natural, -1 size","hp":171,"hd":"12d8+6d6+96","hd_value":18,"fort":15,"ref":10,"will":13,"defensive_abilities":["improved rock catching"],"resists":["acid 10"],"speed":[{"type":"land","speed":40}],"melee":"+1 shortspear +19 (1d8+8)","ranged":"rock +14 (1d8+10)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rock throwing","details":"180 ft."}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"stone shape"},{"spell":"stone tell"},{"spell":"transmute rock to mud"}]},{"frequency":"7/day","spells":[{"spell":"elemental ray","details":"1d6+3 acid"}]}],"spellsknown_caster_level":6,"spellsknown_concentration":10,"spellsknown":[{"spell_level":3,"spell_slots":4,"spells":[{"spell":"fly"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"blur"},{"spell":"glitterdust"},{"spell":"scorching ray"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"burning hands"},{"spell":"charm person"},{"spell":"mage armor"},{"spell":"obscuring mist"},{"spell":"shocking grasp"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mending"},{"spell":"prestidigitation"}]}],"bloodline":"Elemental (earth)","strength":25,"dexterity":15,"constitution":21,"intelligence":14,"wisdom":14,"charisma":18,"baseatk":12,"cmb":20,"cmd":35,"feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Extend Spell"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Spring Attack"}],"skills":[{"skill":"Climb","value":28},{"skill":"Knowledge (arcana)","value":23},{"skill":"Perception","value":20},{"skill":"Spellcraft","value":23}],"languages":["Common","Draconic","Giant","Terran"],"sq":["bloodline arcana (change energy damage spells to match bloodline energy)"],"gear":"+1 shortspear, headband of alluring charisma +2, ring of minor acid resistance, ring of protection +2, potion of barkskin +4","before_combat":"Conna casts mage armor twice a day, so it's always in effect during her waking hours.","during_combat":"Conna's main tactic is to stall. She uses Combat Expertise to increase her AC when she can. If she has time to prepare, she casts fly on herself.","morale":"Conna doesn't want to fight the PCs. Her tactics focus on escape so she can recover in hiding and plan a new method of contacting the PCs and once again try to plead her case and recruit them in her plans against Mokmurian.","source":"RotRL-AE-Fortress of the Stone Giants, Pathfinder RPG Bestiary 151"},{"name":"Galenmir","cr":12,"xp":19200,"race":"stone giant","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":4}],"alignment":"N","size":"Large","type":"humanoid","sub_types":["giant"],"init":1,"senses":["darkvision 60 ft.","low-light vision"],"ac":31,"ac_touch":10,"ac_flat_footed":30,"ac_mods":"+8 armor, +1 Dex, +11 natural, +2 shield, -1 size","hp":160,"hd":"12d8+4d10+84","hd_value":16,"fort":19,"ref":8,"will":10,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1","improved rock catching"],"speed":[{"type":"land","speed":40}],"melee":"+3 heavy pick +24 (1d8+24/19-20/x4) or 2 slams +21 (1d8+19)","ranged":"rock +16 (1d8+16)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rock throwing","details":"180 ft."}],"strength":32,"dexterity":13,"constitution":21,"intelligence":12,"wisdom":12,"charisma":14,"baseatk":13,"cmb":25,"cmd":36,"feats":[{"feat":"Awesome Blow"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (heavy pick)"},{"feat":"Improved Iron Will"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Quick Draw"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (heavy pick)"},{"feat":"Weapon Specialization (heavy pick)"}],"skills":[{"skill":"Climb","value":22},{"skill":"Handle Animal","value":15},{"skill":"Intimidate","value":15},{"skill":"Perception","value":9},{"skill":"Ride","value":12},{"skill":"Stealth","value":10}],"languages":["Common","Giant"],"sq":["armor training 1"],"gear":"+2 breastplate, +1 light steel shield, +3 heavy pick, cloak of elvenkind, 19 pp, 18 gp, 13 sp, potion of heroism, potion of gaseous form, oil of darkness","before_combat":"Galenmir drinks his potion of heroism and uses oil of darkness on his pick (unless the PCs don't seem to be relying on light, in which case he doesn't use this tactic).","during_combat":"Galenmir has stacked several rocks next to the pit entrance to his lair and uses these against intruders. If confronted in close quarters, he uses Improved Bull Rush to keep his enemies from surrounding him and to set himself up for tactical advantages. He always uses Power Attack (these bonuses are included in his stats above).","morale":"Although Galenmir is no coward, he realizes when he's been beaten. If reduced to 30 hit points or fewer, he drinks his potion of gaseous form and seeps into the cracks and crevices of the caves, working his way up and out of the pit to gather a group of eight stone giants to then lead back into the pit to seek out the PCs. While he's aware that Mokmurian will likely be furious at this breach of edict, Galenmir assumes his lord will be even more furious if the PCs are allowed to explore the caves uncontested.","source":"RotRL-AE-Fortress of the Stone Giants, Pathfinder RPG Bestiary 151"},{"name":"Enga Keckvia","cr":11,"xp":12800,"race":"kobold","gender":"Female","age_category":"Adult","classes":[{"class":"barbarian","level":12}],"alignment":"CE","size":"Small","type":"humanoid","sub_types":["reptilian"],"init":2,"senses":["darkvision 60 ft."],"ac":21,"ac_touch":11,"ac_flat_footed":19,"ac_mods":"+7 armor, +2 Dex, +1 natural, -2 rage, +2 shield, +1 size","hp":155,"hd":"12d12+72","hd_value":12,"fort":14,"ref":6,"will":10,"defensive_abilities":["improved uncanny dodge","trap sense +4"],"weaknesses":["light sensitivity; DR 5/-"],"speed":[{"type":"land","speed":30}],"melee":"+3 shortspear +22 (1d4+8)","ranged":"sling +15 (1d3+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"greater rage","details":"27 rounds/day"},{"type":"rage powers","details":"guarded stance [+3 dodge vs. melee], increased damage reduction +3, quick reflexes, renewed vigor [3d8+7 hp]"}],"strength":20,"dexterity":15,"constitution":18,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":12,"cmb":16,"cmd":26,"feats":[{"feat":"Blind-Fight"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (shortspear)"}],"skills":[{"skill":"Craft (trapmaking)","value":17},{"skill":"Perception","value":18},{"skill":"Stealth","value":18},{"skill":"Survival","value":10},{"skill":"Swim","value":11}],"languages":["Common","Draconic"],"sq":["crafty","fast movement"],"gear":"+1 breastplate, +1 buckler, +3 shortspear, sling, 11 gp, 12 sp, 12 cp, necklace of fireballs (type IV)","during_combat":"Enga is brave and fearless, despite (or perhaps due to) her small stature. She rages on the first round of combat and focuses her anger on healers first and foremost.","morale":"Enga flees to the southwest if reduced to fewer than 20 hit points, hoping to lose her tormenters in the mazelike region. If she's got a few rounds, she rigs a quick but deadly trap by removing her necklace of fireballs (but keeping one bead) and leaving it on the ground. She then moves about 60 ft. away and waits; once she sees someone reach the necklace, she throws her bead and detonates the entire necklace at once. She then doubles back to area B7a via a different route and seeks out one of the lamias in area 3 for aid.","source":"RotRL-AE-Fortress of the Stone Giants, Pathfinder RPG Bestiary 183"},{"name":"Lokansir","cr":11,"xp":12800,"race":"hill giant","gender":"Male","age_category":"Adult","alignment":"CE","size":"Huge","type":"humanoid","sub_types":["giant"],"templates_applied":"jotunblood","init":-2,"senses":["low-light vision","scent"],"ac":24,"ac_touch":6,"ac_flat_footed":24,"ac_mods":"-2 Dex, +18 natural, -2 size","hp":147,"hd":"14d8+84","hd_value":14,"fort":15,"ref":2,"will":6,"defensive_abilities":["rock catching"],"sr":22,"speed":[{"type":"land","speed":50}],"melee":"+3 greatclub +22 (3d8+19/19-20)","ranged":"rock +7 (2d6+16)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"earth-shaking bellow"},{"type":"meld into earth"},{"type":"rock throwing","details":"120 ft."}],"strength":33,"dexterity":6,"constitution":23,"intelligence":6,"wisdom":10,"charisma":7,"baseatk":10,"cmb":23,"cmd":31,"feats":[{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (greatclub)"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Staggering Critical"}],"skills":[{"skill":"Climb","value":21},{"skill":"Perception","value":13}],"languages":["Giant"],"special_abilities":[{"type":"Earth-Shaking Bellow","kind":"Su","details":"Once every 1d4 rounds, Lokansir can loose an earth-shaking bellow that functions like an earthquake spell, affecting a 40-foot-cone."},{"type":"Meld Into Earth","kind":"Su","details":"At will, Lokansir can meld into earth (not solid stone) as if using the meld into stone spell, except that he may remain in the earth as long as he wishes. A move earth spell cast upon his location causes him to be expelled from the earth and take 5d6 points of damage. While melded with earth, he gains fast healing 1."}],"gear":"+3 greatclub","during_combat":"Lokansir isn't too bright, and his combat tactics reflect that. He rarely bothers moving around much in combat except to get in reach of enemies to crush them with his favorite club. He avoids using his earth-shaking bellow while underground, but if brought below 50 hit points and unable to merge with earth, he'll use this ability in desperation.","morale":"Lokansir melds into earth if reduced below 50 hit points and waits for his fast healing to heal him completely before emerging. If somehow prevented from using this tactic, the desperate giant tries to flee out of the caves up into Jorgenfist to find more earth to hide in. If he manages to heal back to his full hit points, he tracks down the PCs for revenge.","source":"RotRL-AE-Fortress of the Stone Giants, Pathfinder RPG Bestiary 150, Advanced Bestiary 155"},{"name":"Seleval And Zaelsar Xp 12,800","cr":11,"xp":12800,"race":"lamia","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of Lamashtu","level":8}],"alignment":"CE","size":"Large","type":"monstrous humanoid","init":4,"senses":["darkvision 60 ft.","low-light vision"],"ac":27,"ac_touch":16,"ac_flat_footed":22,"ac_mods":"+4 armor, +2 deflection, +4 Dex, +1 dodge, +7 natural, -1 size","hp":161,"hd":"9d10+8d8+76","hd_value":17,"fort":13,"ref":14,"will":21,"speed":[{"type":"land","speed":30}],"melee":"+2 falchion +22 (2d6+11/15-20), 2 claws +15 (1d6+3) or touch +18 (1d4 Wisdom drain)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"6/day, DC 17, 4d6"},{"type":"might of the gods","details":"+8, 8 rounds/day"},{"type":"scythe of evil","details":"4 rounds, 1/day"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"disguise self"},{"spell":"ventriloquism"}]},{"frequency":"1/day","spells":[{"spell":"deep slumber"}]},{"frequency":"3/day","spells":[{"spell":"charm monster"},{"spell":"major image"},{"spell":"mirror image"},{"spell":"suggestion"}]},{"frequency":"10/day","spells":[{"spell":"strength surge","details":"+4"},{"spell":"touch of evil","details":"4 rounds"}]}],"spellsprepared_caster_level":8,"spellsprepared_concentration":15,"spellsprepared":[{"spell_level":4,"spell_slots":4,"spells":[{"spell":"freedom of movement"},{"spell":"poison"},{"spell":"sending"},{"spell":"unholy blight","type":"domain"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"blindness/deafness"},{"spell":"cure serious wounds","count":2},{"spell":"dispel magic"},{"spell":"magic vestment","type":"domain"},{"spell":"stone shape"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"bull's strength","type":"domain"},{"spell":"cure moderate wounds","count":3},{"spell":"death knell"},{"spell":"hold person"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command"},{"spell":"cure light wounds","count":3},{"spell":"divine favor"},{"spell":"protection from good","type":"domain"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"mending"},{"spell":"read magic"}]}],"spelldomains":"Evil, Strength","strength":18,"dexterity":18,"constitution":18,"intelligence":11,"wisdom":24,"charisma":16,"baseatk":15,"cmb":22,"cmd":39,"cmd_special":"43 vs. trip","feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Improved Critical (falchion)"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Selective Channeling"},{"feat":"Spring Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":20},{"skill":"Knowledge (religion)","value":12},{"skill":"Linguistics","value":4},{"skill":"Perception","value":27},{"skill":"Spellcraft","value":11}],"languages":["Common","Abyssal","Giant"],"sq":["undersized weapons"],"gear":"masterwork leather armor, +2 falchion, headband of inspired wisdom +2, ring of protection +2","before_combat":"Each lamia casts magic vestment at the start of her day-if the PCs arrive at this room after sundown, that spell has expired. If the lamias hear the dragons or trolls fighting to the north or south, they take several rounds to cast preparatory spells (freedom of movement, bull's strength, mirror image, and finally protection from good) before moving into the neighboring room to join the battle.","during_combat":"Each lamia casts divine favor on the first round of combat, then moves in to fight the enemy in melee. They focus their attacks on the same target, one lamia attacking with her melee attacks while the other casts spells at the target, then they switch off the next round. These lamias are merciless, and if one of them drops to negative hit points, the other doesn't hesitate to use death knell on her dying sister.","morale":"If a lamia is reduced to 40 hit points or fewer, she tries to cast sanctuary and then uses her healing magic on herself while attempting to put some distance between her and the PCs. If reduced to 20 hit points, a lamia casts sending to warn Mokmurian before she attempts to flee to another room in this complex, where she can find an ally to aid her.","source":"RotRL-AE-Fortress of the Stone Giants, Pathfinder RPG Bestiary 186"},{"name":"Hurek And Durek","cr":10,"xp":9600,"race":"troll","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":5}],"alignment":"CE","size":"Large","type":"humanoid","sub_types":["giant"],"init":7,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":25,"ac_touch":12,"ac_flat_footed":22,"ac_mods":"+8 armor, +3 Dex, +5 natural, -1 size","hp":136,"hd":"6d8+5d10+82","hd_value":11,"hp_mods":"regeneration 5 (acid or fire)","fort":16,"ref":6,"will":6,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":30}],"melee":"bite +17 (1d8+9), 2 claws +18 (1d6+11) or +2 ranseur +19 (2d6+12/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d6+7"},{"type":"weapon training","details":"natural +1"}],"strength":26,"dexterity":16,"constitution":25,"intelligence":6,"wisdom":13,"charisma":6,"baseatk":9,"cmb":18,"cmd":31,"feats":[{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (claws)"},{"feat":"Weapon Focus (ranseur)"},{"feat":"Weapon Specialization (claws)"},{"feat":"Weapon Specialization (ranseur)"}],"skills":[{"skill":"Climb","value":14},{"skill":"Perception","value":10}],"languages":["Giant"],"sq":["armor training 1"],"gear":"+2 breastplate, +2 ranseur","during_combat":"The trolls fight with their +2 ranseurs through the narrow windows as long as they can, gaining a +4 cover bonus to their AC and on Reflex saves against foes attacking them from the central passageway. As soon as anyone manages to get into one of the side caves, they drop their ranseurs and continue the fight with their claws and teeth. The trolls don't coordinate their attacks in any way, simply fighting as long as they can.","morale":"These brutish trolls trust their regeneration implicitly to keep them alive. They fight to the death, even in the face of foes who use acid and fire.","source":"RotRL-AE-Fortress of the Stone Giants, Pathfinder RPG Bestiary 268"},{"name":"The Headless Lord","cr":11,"xp":12800,"race":"ogre  undead lord","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":6}],"alignment":"NE","size":"Large","type":"undead","templates_applied":"fast zombie","init":6,"senses":["darkvision 60 ft."],"auras":["desecration (20-ft. radius)"],"ac":28,"ac_touch":11,"ac_flat_footed":26,"ac_mods":"+10 armor, +2 Dex, +7 natural, -1 size","hp":126,"hd":"6d8+6d10+66","hd_value":12,"fort":14,"ref":9,"will":10,"save_mods":"+2 vs. fear","defensive_abilities":["bravery +2 channel resistance +4"],"dr":"10/magic","immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"runechill hatchet +21 (1d8+15/19-20/x3), runechill hatchet +21 (1d8+10/19-20/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"create spawn"},{"type":"quick strikes"},{"type":"weapon training","details":"axes +1"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"darkness"},{"spell":"fear"},{"spell":"summon","details":"9 Human fast zombies, level 5"}]}],"strength":31,"dexterity":15,"intelligence":10,"wisdom":14,"charisma":18,"baseatk":10,"cmb":21,"cmd":33,"feats":[{"feat":"Cleave"},{"feat":"Command Undead"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (handaxe)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (handaxe)"},{"feat":"Weapon Specialization (handaxe)"}],"skills":[{"skill":"Climb","value":21},{"skill":"Intimidate","value":19},{"skill":"Perception","value":17}],"languages":["Giant","telepathy 100 ft. (undead only)"],"sq":["armor training 1","headless"],"special_abilities":[{"type":"Command Undead","kind":"Su","details":"The headless lord can use its Command Undead feat seven times per day to command any type of zombie as if it were a 12th-level cleric."},{"type":"Create Spawn","kind":"Su","details":"A creature slain by the Headless Lord rises in 1d4 minutes as a fast zombie under the Headless Lord's control."},{"type":"Desecration Aura","kind":"Su","details":"The Headless Lord constantly projects a 20-foot-radius aura that functions as a desecrate spell."},{"type":"Headless","kind":"Ex","details":"Although the Headless Lord lacks a head, it can still hear and see and speak as if it had one."},{"type":"Undead Telepathy","kind":"Su","details":"The Headless Lord can communicate telepathically with any other undead creature within 100 feet. It can use this telepathic communication to direct mindless undead as a free action."}],"gear":"+1 full plate, runechill hatchets (2)","during_combat":"The Headless Lord orders its four hill giant zombies to attack as soon as foes enter this room, or if it sees someone outside preparing to use ranged attacks. The Headless Lord casts fear on the PCs once it can catch at least three of them in the area of effect. It summons nine fast zombies to help flank foes, block charges, or provide cover, keeping as many as it can within its aura of desecration.","morale":"The Headless Lord fights until destroyed.","source":"RotRL-AE-Fortress of the Stone Giants, Pathfinder RPG Bestiary 289, Tome of Horrors Complete 748"},{"name":"Clockwork Librarian","cr":6,"xp":2400,"race":"clockwork servant","age_category":"Adult","classes":[{"class":"expert","level":8}],"alignment":"LN","size":"Medium","type":"construct","sub_types":["clockwork"],"templates_applied":"awakened","init":6,"senses":["darkvision 60 ft.","low-light vision"],"ac":17,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+2 Dex, +3 dodge, +2 natural","hp":67,"hd":"2d10+8d8+20","hd_value":10,"fort":2,"ref":6,"will":6,"immunities":["construct traits"],"weaknesses":["vulnerable to electricity"],"speed":[{"type":"land","speed":30}],"melee":"slam +11 (1d4+4).","ranged":"net +10","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":14,"intelligence":12,"wisdom":11,"charisma":5,"baseatk":8,"cmb":11,"cmd":26,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Improved Lightning Reflexes"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"}],"skills":[{"skill":"Appraise","value":14},{"skill":"Craft (bookbinding)","value":14},{"skill":"Knowledge (arcana)","value":14},{"skill":"Knowledge (geography)","value":14},{"skill":"Knowledge (nobility)","value":14},{"skill":"Linguistics","value":14},{"skill":"Perception","value":13}],"languages":["Abyssal","Aklo","Aquan","Auran","Azlanti","Draconic","Elven","Giant","Ignan","Infernal","Terran","Thassilonian"],"special_abilities":[{"type":"Awakened Clockwork","kind":"Su","details":"The methods by which the clockwork librarian's long-dead creators granted it intelligence have long since been lost."}],"gear":"ring of levitation (as boots of levitation), net, windup key","during_combat":"The clockwork librarian isn't a war construct and only fights to defend itself or the library.","morale":"Although relatively ineffectual in combat, the clockwork librarian defends the library until it is destroyed.","source":"RotRL-AE-Fortress of the Stone Giants, Pathfinder RPG Bestiary 3 56"},{"name":"Mokmurian","cr":15,"xp":51200,"race":"stone giant","gender":"Male","age_category":"Adult","classes":[{"class":"transmuter","level":11}],"alignment":"CE","size":"Large","type":"humanoid","sub_types":["giant"],"init":7,"senses":["darkvision 60 ft.","low-light vision","see invisibility"],"ac":32,"ac_touch":13,"ac_flat_footed":28,"ac_mods":"+4 armor, +3 Dex, +1 dodge, +11 natural, +4 shield, -1 size","hp":287,"hd":"12d8+11d6+195","hd_value":23,"fort":19,"ref":10,"will":15,"defensive_abilities":["improved rock catching"],"dr":"10/adamantine (against first 110 points of damage)","resists":["fire 30 (or an energy type favored by the party)"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":40}],"melee":"+2 defending spell-storing (vampiric touch) club +22 (1d8+9) or 2 slams +20 (1d8+7)","ranged":"rock +17 (1d8+10)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rock throwing","details":"180 ft."}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"change shape","details":"11 rounds/day, beast shape II/elemental body I"}]},{"frequency":"8/day","spells":[{"spell":"telekinetic fist","details":"1d4+5 bludgeoning"}]}],"spellsprepared_caster_level":11,"spellsprepared_concentration":16,"spellsprepared":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"disintegrate","count":2},{"spell":"quickened scorching ray"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"cloudkill"},{"spell":"quickened shield"},{"spell":"telekinesis","count":2},{"spell":"wall of force"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"dimension door"},{"spell":"fire shield"},{"spell":"mass reduce person","count":2},{"spell":"solid fog"},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"fly"},{"spell":"greater magic weapon"},{"spell":"slow","count":2},{"spell":"stinking cloud"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"fog cloud"},{"spell":"glitterdust"},{"spell":"resist energy"},{"spell":"scorching ray"},{"spell":"see invisibility"},{"spell":"whispering wind","count":2}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"alarm"},{"spell":"enlarge person"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"protection from good"},{"spell":"ray of enfeeblement"},{"spell":"reduce person","count":2}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"light"},{"spell":"mage hand"},{"spell":"prestidigitation"},{"spell":"touch of fatigue"}]}],"prohibited_schools":"Enchantment, Illusion","strength":25,"dexterity":17,"constitution":27,"intelligence":20,"wisdom":14,"charisma":14,"baseatk":14,"cmb":22,"cmd":36,"feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wand"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Quicken Spell"},{"feat":"Scribe Scroll"},{"feat":"Spring Attack"},{"feat":"Vital Strike"},{"feat":"Whirlwind Attack"}],"skills":[{"skill":"Climb","value":33},{"skill":"Fly","value":10},{"skill":"Knowledge (arcana)","value":31},{"skill":"Knowledge (engineering)","value":31},{"skill":"Knowledge (geography)","value":31},{"skill":"Perception","value":25},{"skill":"Spellcraft","value":31},{"skill":"Stealth","value":22}],"languages":["Common","Aklo","Draconic","Giant","Orc","Terran","Thassilonian"],"sq":["arcane bond (club)","physical enhancement +3"],"gear":"+1 defending spell-storing (vampiric touch) club, bag of holding (type II), fog-cutting lenses, robe of runes, key to area C7, 500 gp in diamond dust, spellbooks Spellbooks Mokmurian keeps his spellbooks in his bag of holding. Apart from containing all of the spells he has prepared, this extensive collection also contains most of the spells in the Core Rulebook, up through and including 6th-level spells. Feel free to introduce new spells from other sources via these books-if you do, you should also consider swapping some of these spells in for those he normally prepares., scroll of limited wish, wand of bear's endurance (13 charges)","before_combat":"Mokmurian casts mage armor and greater magic weapon on his club every morning after he prepares his spells. Once he learns that the PCs are coming (likely via the headless ogre's head), he casts resist energy (to resist a type of energy he knows the PCs favor, or otherwise fire), see invisibility, and stoneskin. If he suspects the PCs are very close, he casts fly and uses his wand of bear's endurance. All of these effects are incorporated into his stats above. He then casts fog cloud near the entrance to the room and waits to ambush the PCs.","during_combat":"Mokmurian's first action when the PCs enter his room is to cast solid fog, catching as many of them as possible in the spell's area of effect. He uses his fog-cutting lenses so he can target the PCs with ease with his ranged attack spells. As soon as someone emerges from the fog, he casts cloudkill on that area, followed by stinking cloud. If a PC gets too close to him, he uses telekinesis to hurl her across the room and hopefully back into one of the fog spell effects. His goal is to maintain range superiority on his enemies, but if melee seems inevitable, he casts mass reduce person first to shrink down foes, coupling that with his quickened shield spell. Then, on the first round of actual melee, he casts enlarge person on himself and begins making melee attacks. If any hounds of Tindalos survive, he calls on them to aid him in battle as well.","morale":"Mokmurian fights until reduced to 40 hit points or fewer, at which point he uses dimension doors to retreat to area 3, hoping to get healing from his lamia minions. If they're dead, he flees up to the surface and gathers a group of a dozen stone giants and any of the named giants who still live to mount an attack on the library to finish off the PCs. If the PCs have secured an alliance with Conna and she still lives, she's among the giants whom Mokmurian recruits-when and if this patrol encounters the PCs, Conna switches sides to aid them, a move that throws the other stone giants into chaos. The next round, half of those giants defect as well, renouncing Mokmurian as an unworthy runt and joining Conna and the PCs against him. In this event, Mokmurian fights again until reduced to fewer than 30 hit points, then tries to use his scroll of limited wish to teleport to Xin-Shalast. Yet unfortunately for him, Karzoug, who has been watching his actions through the link their souls have shared ever since Mokmurian's trip to the City of Greed, has other plans for him.","source":"RotRL-AE-Fortress of the Stone Giants, Pathfinder RPG Bestiary 151"},{"name":"The Scribbler","cr":14,"xp":38400,"race":"Azlanti Human","gender":"Male","age_category":"Adult","classes":[{"class":"cleric of Lamashtu","level":12},{"class":"fighter","level":2}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["chaotic","evil","human"],"templates_applied":"divine guardian","init":7,"ac":27,"ac_touch":18,"ac_flat_footed":23,"ac_mods":"+9 armor, +4 deflection, +3 Dex, +1 dodge, +0 natural","hp":150,"hd":"12d8+2d10+82","hd_value":14,"hp_mods":"fast healing 5","fort":15,"ref":7,"will":18,"save_mods":"+1 vs. fear","defensive_abilities":["ability healing","bravery +1","freedom of movement"],"dr":"10/adamantine","immunities":["disease","mind-affecting effects","poison"],"sr":26,"speed":[{"type":"land","speed":40,"special":"60 ft. base"}],"melee":"fanged falchion +19 (2d4+9/15-20)","ranged":"+1 cold iron returning dagger +15 (1d4+5/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"5/day, DC 18, 6d6"},{"type":"might of the gods","details":"+12, 12 rounds/day"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dimension door","details":"limited to Lamashtu's shrine"},{"spell":"master's illusion","details":"12 rounds/day"}]},{"frequency":"1/day","spells":[{"spell":"arcane lock"},{"spell":"augury"},{"spell":"clairaudience/clairvoyance"},{"spell":"commune"},{"spell":"dismissal"},{"spell":"forbiddance"},{"spell":"guards and wards"}]},{"frequency":"3/day","spells":[{"spell":"alarm"},{"spell":"knock"}]},{"frequency":"11/day","spells":[{"spell":"copycat","details":"12 rounds"},{"spell":"strength surge","details":"+6"}]}],"spellsprepared_caster_level":12,"spellsprepared_concentration":20,"spellsprepared":[{"spell_level":6,"spell_slots":4,"spells":[{"spell":"heal"},{"spell":"quickened spiritual weapon"},{"spell":"stoneskin","type":"domain"},{"spell":"summon monster VI"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"extended greater magic weapon"},{"spell":"quickened divine favor"},{"spell":"quickened shield of faith"},{"spell":"righteous might","type":"domain"},{"spell":"spell resistance"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"confusion","type":"domain"},{"spell":"cure critical wounds"},{"spell":"divine power"},{"spell":"extended magic vestment"},{"spell":"freedom of movement"},{"spell":"poison"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"blindness/deafness"},{"spell":"cure serious wounds","count":2},{"spell":"dispel magic"},{"spell":"nondetection","type":"domain"},{"spell":"protection from energy"},{"spell":"summon monster III"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"bear's endurance"},{"spell":"bull's strength"},{"spell":"cure moderate wounds","count":2},{"spell":"gentle repose"},{"spell":"hold person"},{"spell":"invisibility","type":"domain"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command"},{"spell":"cure light wounds","count":2},{"spell":"disguise self","type":"domain"},{"spell":"obscuring mist"},{"spell":"protection from good"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"guidance"},{"spell":"light"},{"spell":"read magic"}]}],"spelldomains":"Strength, Trickery","strength":18,"dexterity":16,"constitution":19,"intelligence":12,"wisdom":26,"charisma":14,"baseatk":11,"cmb":15,"cmd":33,"feats":[{"feat":"Craft Magic Arms and Armor"},{"feat":"Dodge"},{"feat":"Extend Spell"},{"feat":"Improved Critical (falchion)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Quicken Spell"},{"feat":"Skill Focus (Bluff)"},{"feat":"Toughness"},{"feat":"Weapon Focus (falchion)"}],"skills":[{"skill":"Bluff","value":15},{"skill":"Intimidate","value":12},{"skill":"Knowledge (arcana, planes, religion)","value":11},{"skill":"Perception","value":20},{"skill":"Perform (oratory)","value":9},{"skill":"Sense Motive","value":13},{"skill":"Spellcraft","value":11}],"languages":["Abyssal","Thassilonian"],"sq":["blessed life","sacred site"],"special_abilities":[{"type":"Ability Healing","kind":"Ex","details":"The Scribbler heals 1 point of ability damage per round in each damaged ability score."},{"type":"Blessed Life","kind":"Ex","details":"The Scribbler doesn't age or breathe and doesn't require food, drink, or sleep."},{"type":"Divine Swiftness","kind":"Ex","details":"The Scribbler gains a +4 bonus on initiative checks and his base speed is 60 ft. (or 40 ft. when wearing his +1 breastplate)."},{"type":"Sacred Site","kind":"Ex","details":"The Scribbler is bound to the shrine of Lamashtu (areas A1-A10), and has been charged by the goddess of nightmares herself with keeping the site sacred and free from intruders and heretics. Should the Scribbler ever move beyond these areas, he loses the divine guardian template and his spellcasting ability until he atones and reenters the site within 1 week. Otherwise, he loses the template permanently and takes 6d6 points of Constitution drain as his body adjusts to the loss."}],"gear":"+1 breastplate, fanged falchion, +1 cold iron returning dagger, headband of inspired wisdom +2, 750 gp in diamond dust","before_combat":"Every day, the Scribbler wards the complex by casting alarm and guards and wards. He also casts nondetection, extended magic vestment, and extended greater magic weapon every day after finishing his daily prayers to Lamashtu. If he has time just before combat begins, he casts stoneskin, spell resistance, freedom of movement, bull's strength, and bear's endurance.","during_combat":"The Scribbler starts combat by casting summon monster VI to summon 1d3 babaus. While these summoned monsters engage his foes, he casts righteous might and quickened divine favor. He then enters combat, casting a quickened spiritual weapon on that round to attack a spellcaster or healer.","morale":"The Scribbler uses dimension door to retreat to the hallway outside of area A10 if brought below 10 hit points, then hides inside his lair and heals his wounds before returning to continue a fight with intruders. If confronted in area A10, he fights to the death.","source":"RotRL-AE-Sins of the Saviors, Advanced Bestiary 60"},{"name":"Hound Of Lamashtu","cr":6,"xp":2400,"race":"yeth hound","age_category":"Adult","alignment":"NE","size":"Medium","type":"outsider","sub_types":["evil","extraplanar"],"init":8,"senses":["darkvision 60 ft.","scent"],"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+4 Dex, +1 dodge, +5 natural","hp":76,"hd":"8d10+32","hd_value":8,"fort":10,"ref":10,"will":6,"dr":"5/silver","speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":40}],"melee":"bite +13 (2d6+5 plus sinister bite and trip), sting +13 (1d6+5 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bay","details":"DC 16"},{"type":"sinister bite","details":"DC 18"}],"strength":21,"dexterity":19,"constitution":19,"intelligence":10,"wisdom":18,"charisma":14,"baseatk":8,"cmb":13,"cmd":28,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Fly)"}],"skills":[{"skill":"Acrobatics","value":12,"special":"+4 when jumping"},{"skill":"Fly","value":22},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":15},{"skill":"Survival","value":12}],"languages":["Abyssal (cannot speak)"],"sq":["flight"],"during_combat":"The hounds of Lamashtu prefer to surround enemies and attack the same foes. They eagerly attack PCs bearing the symbols of good-aligned deities in favor of other less obviously devoted individuals.","morale":"The hounds are relentless and fight to the death.","source":"RotRL-AE-Sins of the Saviors, Pathfinder RPG Bestiary 286"},{"name":"Fiendish Mustard Jelly","cr":14,"xp":38400,"race":"mustard jelly","age_category":"Adult","alignment":"CE","size":"Large","type":"ooze","sub_types":["extraplanar"],"templates_applied":"fiendish","init":5,"senses":["blindsight 60 ft.","darkvision 60 ft."],"auras":["toxic gas (10 ft., DC 23)"],"ac":25,"ac_touch":15,"ac_flat_footed":19,"ac_mods":"+5 Dex, +1 dodge, +10 natural, -1 size","hp":230,"hd":"20d8+140","hd_value":20,"fort":14,"ref":14,"will":12,"defensive_abilities":["divide","energy absorption"],"dr":"10/good","immunities":["ooze traits"],"resists":["cold 15","fire 15"],"sr":22,"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"4 slams +22 (2d6+7 plus 1d6 acid and grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"acid"},{"type":"constrict","details":"2d6+10 plus 1d6 acid"},{"type":"smite good","details":"1/day, +3 attack, +20 damage"}],"strength":24,"dexterity":20,"constitution":24,"intelligence":14,"wisdom":17,"charisma":16,"baseatk":15,"cmb":23,"cmb_special":"+27 grapple","cmd":39,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Improved Critical (slams)"},{"feat":"Improved Natural Attack (slams)"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (slams)"}],"skills":[{"skill":"Climb","value":28},{"skill":"Perception","value":24},{"skill":"Stealth","value":22},{"skill":"Swim","value":36}],"languages":["Abyssal (cannot speak)"],"special_abilities":[{"type":"Divide","kind":"Ex","details":"As a standard action, a mustard jelly can split into two identical jellies, each with half the original's hit points (round down). A mustard jelly with 10 hit points or fewer cannot divide itself. When divided, each jelly moves at a speed of 40 feet."},{"type":"Energy Absorption","kind":"Ex","details":"A mustard jelly is immune to electricity and magic missiles. If targeted by such an effect, it gains temporary hit points equal to the damage that attack would have normally done. These temporary hit points last for 1 hour."},{"type":"Toxic Gas","kind":"Ex","details":"A mustard jelly exudes an aura of toxic gas in a 10-ft.-radius spread. A creature in this area must succeed at a DC 23 Fortitude save each round or be slowed (as per slow) for as long as it remains in the area plus an additional 1d4 rounds. This is a poison effect. The save DC is Constitution-based."}],"during_combat":"The fiendish mustard jelly waits until someone tries to step more than 5 ft. into the room to attack.","morale":"The fiendish mustard jelly fights to the death.","source":"RotRL-AE-Sins of the Saviors, Tome of Horrors Complete 385, Pathfinder RPG Bestiary 294"},{"name":"Thassilonian Mummy","cr":7,"xp":3200,"race":"mummy","age_category":"Adult","alignment":"LE","size":"Medium","type":"undead","init":6,"senses":["darkvision 60 ft."],"auras":["despair (30 ft., paralyzed for 1d4 rounds, Will DC 19 negates)"],"ac":22,"ac_touch":12,"ac_flat_footed":20,"ac_mods":"+2 Dex, +10 natural","hp":95,"hd":"10d8+50","hd_value":10,"fort":9,"ref":9,"will":13,"dr":"5/-","immunities":["undead traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":30}],"melee":"slam +19 (1d8+14 plus mummy rot)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"mummy rot","details":"DC 19"}],"strength":28,"dexterity":14,"intelligence":10,"wisdom":19,"charisma":19,"baseatk":7,"cmb":18,"cmd":30,"feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Acrobatics","value":13},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":18},{"skill":"Stealth","value":16}],"languages":["Thassilonian"],"during_combat":"These mummies focus their wrath on any envious or lustful characters in the group. They don't attack gluttonous characters unless such characters attack them first.","morale":"The mummies fight until destroyed, pursuing foes throughout the crypts but not back into the Runeforge hub.","source":"RotRL-AE-Sins of the Saviors, Pathfinder RPG Bestiary 210"},{"name":"Xyoddin Xerriock","cr":13,"xp":25600,"race":"Human(azlanti) ravenous dread zombie Human","gender":"Male","age_category":"Adult","classes":[{"class":"aristocrat","level":4},{"class":"rogue","level":9}],"alignment":"CE","size":"Medium","type":"undead","sub_types":["human"],"init":8,"senses":["darkvision 60 ft.","low-light vision"],"auras":["unnatural aura"],"ac":26,"ac_touch":15,"ac_flat_footed":21,"ac_mods":"+7 armor, +4 Dex, +1 dodge, +4 natural","hp":218,"hd":"9d8+4d8+156","hd_value":13,"hp_mods":"fast healing 10","fort":17,"ref":14,"will":11,"defensive_abilities":["cannibalistic healing","channel resistance +2","evasion","improved uncanny dodge","trap sense +3"],"dr":"5/-","immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"+1 Human bane dagger +20 (1d4+9/19-20), bite +18 (1d4+11)","ranged":"mwk dagger +17 (1d4+8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"brain consumption"},{"type":"command zombies"},{"type":"favored prey","details":"humans"},{"type":"hungry special attacks"},{"type":"sneak attack","details":"+5d6"},{"type":"sprint"}],"strength":24,"dexterity":18,"intelligence":13,"wisdom":12,"charisma":30,"baseatk":9,"cmb":18,"cmb_special":"+20 grapple","cmd":33,"cmd_special":"35 vs. grapple","feats":[{"feat":"Blind-Fight"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Dazzling Display"},{"feat":"Dodge"},{"feat":"Greater Feint"},{"feat":"Improved Feint"},{"feat":"Improved Grapple"},{"feat":"Improved Initiative"},{"feat":"Improved Unarmed Strike"},{"feat":"Mobility"},{"feat":"Shatter Defenses"},{"feat":"Toughness"},{"feat":"Weapon Focus (dagger)"}],"skills":[{"skill":"Acrobatics","value":28},{"skill":"Bluff","value":27},{"skill":"Climb","value":15},{"skill":"Diplomacy","value":27},{"skill":"Escape Artist","value":24},{"skill":"Intimidate","value":31},{"skill":"Knowledge (nobility)","value":18},{"skill":"Perception","value":26},{"skill":"Perform (string)","value":20},{"skill":"Sense Motive","value":18},{"skill":"Stealth","value":24},{"skill":"Survival","value":10}],"languages":["Giant","Thassilonian"],"sq":["rogue talents (bleeding attack +5, combat trick, surprise attack, weapon training)","trapfinding +4"],"special_abilities":[{"type":"Brain Consumption","kind":"Ex","details":"When Xyoddin makes a successful grapple check to deal damage with his bite against a pinned or helpless living foe, the victim takes 2d4 points of Intelligence drain as Xyoddin consumes portions of his brain. A successful DC 23 Fortitude save halves this Intelligence drain. A creature reduced to 0 Intelligence by this attack is slain. Creatures immune to critical hits and those with multiple heads are not killed by this attack. The save DC is Strength-based."},{"type":"Cannibalistic Healing","kind":"Ex","details":"So long as Xyoddin has fed on Human flesh within the last 24 hours, he gains fast healing 10."},{"type":"Command Zombies","kind":"Su","details":"Xyoddin can automatically command all normal zombies within 30 ft. as a free action. Normal zombies never attack him unless they are compelled."},{"type":"Favored Prey","kind":"Ex","details":"Xyoddin gains a +2 bonus on damage rolls against humanoids and a +2 bonus on Bluff, Perception, Sense Motive, and Survival checks when using these skills against humanoids. Against humans, these bonuses increase to +4."},{"type":"Hungry Special Attacks","kind":"Ex","details":"Humans take a -2 penalty on saving throws against Xyoddin's special attacks."},{"type":"Ravenous Body","kind":"Su","details":"Normally, Xyoddin must eat Human flesh at least once every 3 days or he begins to starve, but the sustaining presence radiated by Runeforge prevents this."},{"type":"Sprint","kind":"Ex","details":"Once per day, Xyoddin can move at a speed of 300 ft. when he makes a charge."},{"type":"Telepathic Bond","kind":"Sp","details":"Xyoddin has a permanent telepathic bond with Azaven."},{"type":"Unnatural Aura","kind":"Su","details":"Any animal within 30 ft. of Xyoddin must succeed at a DC 26 Will save or become panicked, remaining so for as long as it remains within this proximity. This is a mind-affecting fear effect."}],"gear":"+3 chain shirt, +1 Human bane dagger,  masterwork dagger, amulet of natural armor +2, cloak of resistance +1, 146 gp","before_combat":"Xyoddin tears free a portion of the torso's liver and eats it before combat begins if he has a chance, gaining the benefits of fast healing 10 for the fight to come.","during_combat":"If faced with enemies that include humans in their ranks, Xyoddin's terrible hunger pulls him to them, causing him to ignore all non-Human targets. He's able to hold back his ravenous urgings enough to resist taking the time to feast on a slain Human if other enemies remain to defeat, but only barely.","morale":"Xyoddin fights until destroyed.","source":"RotRL-AE-Sins of the Saviors, Advanced Bestiary 105, 211"},{"name":"Azaven","cr":15,"xp":51200,"race":"Azlanti Human","gender":"Male","age_category":"Adult","classes":[{"class":"necromancer","level":14}],"alignment":"CE","size":"Medium","type":"undead","sub_types":["augmented humanoid","human"],"templates_applied":"lich","init":8,"senses":["darkvision 60 ft.","life sight"],"auras":["fear (60-ft. radius, DC 23)"],"ac":27,"ac_touch":17,"ac_flat_footed":22,"ac_mods":"+5 armor, +2 deflection, +4 Dex, +1 dodge, +5 natural","hp":179,"hd":"14d6+128","hd_value":14,"fort":10,"ref":10,"will":14,"defensive_abilities":["channel resistance +4","rejuvenation"],"dr":"15/bludgeoning and magic","immunities":["cold","electricity","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"touch +9 (1d8+8 plus paralyzing touch)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"DC 21, 11/day"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"11/day","spells":[{"spell":"grave touch","details":"7 rounds"}]}],"spellsprepared_caster_level":14,"spellsprepared_concentration":22,"spellsprepared":[{"spell_level":7,"spell_slots":5,"spells":[{"spell":"finger of death"},{"spell":"prismatic spray"},{"spell":"quickened displacement"},{"spell":"quickened vampiric touch","count":2}]},{"spell_level":6,"spell_slots":6,"spells":[{"spell":"chain lightning"},{"spell":"disintegrate"},{"spell":"mislead"},{"spell":"quickened blindness/deafness","count":2},{"spell":"quickened cat's grace"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"fabricate"},{"spell":"quickened magic missile"},{"spell":"telekinesis"},{"spell":"wall of force"},{"spell":"waves of fatigue","count":2}]},{"spell_level":4,"spell_slots":8,"spells":[{"spell":"bestow curse"},{"spell":"contagion"},{"spell":"dimension door"},{"spell":"enervation","count":2},{"spell":"fear"},{"spell":"mass reduce person"},{"spell":"stone shape"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"extended false life"},{"spell":"fly"},{"spell":"gaseous form"},{"spell":"ray of exhaustion","count":2},{"spell":"slow"},{"spell":"stinking cloud"},{"spell":"tongues"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"blindness/deafness","count":2},{"spell":"ghoul touch"},{"spell":"glitterdust"},{"spell":"invisibility"},{"spell":"mirror image"},{"spell":"scorching ray"},{"spell":"spectral hand"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"chill touch","count":2},{"spell":"grease"},{"spell":"magic missile","count":3},{"spell":"obscuring mist"},{"spell":"reduce person"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"prestidigitation"}]}],"prohibited_schools":"abjuration, enchantment","strength":10,"dexterity":18,"intelligence":26,"wisdom":17,"charisma":18,"baseatk":7,"cmb":9,"cmd":26,"feats":[{"feat":"Combat Casting"},{"feat":"Command Undead"},{"feat":"Craft Staff"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Extend Spell"},{"feat":"Greater Spell Focus (necromancy)"},{"feat":"Improved Initiative"},{"feat":"Quicken Spell"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (necromancy)"},{"feat":"Toughness"}],"skills":[{"skill":"Craft (alchemy)","value":26},{"skill":"Knowledge (arcana, dungeoneering, engineering, nobility, planes, and religion)","value":26},{"skill":"Perception","value":29},{"skill":"Sense Motive","value":29},{"skill":"Spellcraft","value":26},{"skill":"Stealth","value":30}],"languages":["Abyssal","Aklo","Draconic","Elven","Giant","Ignan","Infernal","Necril","Thassilonian; telepathic bond","tongues"],"sq":["arcane bond (staff of hungry shadows)","life sight (20 feet, 14 rounds/day)"],"special_abilities":[{"type":"Contingency","kind":"Sp","details":"If Azaven is grappled, a dimension door spell activates on him. Azaven uses this to merely reposition himself in combat if the battle is going well-if it is going poorly, he uses it to flee to area F11."},{"type":"Telepathic Bond","kind":"Sp","details":"Azaven has a permanent telepathic bond with his minion Xyoddin and with one of the Thassilonian mummies in areas F1 and F8."}],"gear":"bracers of armor +5, headband of vast intelligence +4 (grants ranks in Knowledge [nobility] and Spellcraft), ring of protection +2, contingency statuette worth 2,000 gp, staff of hungry shadows (10 charges)","before_combat":"Once he knows interlopers have invaded the crypts, Azaven casts extended false life and tongues on himself. He then calls a devourer-a proud being named Vioidzhain, scarred with symbols only it knows the otherworldly source of-to guard him using his staff of hungry shadows. As soon as he can before combat, he casts quickened cat's grace.","during_combat":"Azaven opens battles by casting finger of death at a spellcaster and quickened displacement on himself. He then casts wall of force to seal himself off from the PCs, giving him time to cast fly, mirror image, and spectral hand. During this time, he lets the conjured devourer keep the PCs busy. If the PCs haven't breached his wall by the time he's done casting preparatory spells, he uses dimension door to return back into their midst and begins casting offensive spells. If he needs more minions, Azaven casts stone shape on a nearby wall to release several wraiths, hoping they provide additional distractions.","morale":"Azaven values his own immortal existence too much to stick around in a fight he's losing. If reduced to fewer than 30 hit points, he uses mislead to escape by casting gaseous form and retreating to area F11, where he gathers his phylactery before triggering the trap in the room to heal his damage. Given time, he recovers his spells and then seeks revenge on the PCs. If confronted there, Azaven has little choice but to fight until destroyed, but he makes sure to trigger the trap in the room before a fight begins.","source":"RotRL-AE-Sins of the Saviors, Pathfinder RPG Bestiary 188"},{"name":"Ordikon, The Mithral Mage","cr":14,"xp":38400,"race":"Human(azlanti)","gender":"Male","age_category":"Adult","classes":[{"class":"transmuter","level":13}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"templates_applied":"mithral-clad","init":4,"ac":31,"ac_touch":15,"ac_flat_footed":26,"ac_mods":"+4 armor, +4 Dex, +1 dodge, +8 natural, +4 shield","hp":169,"hd":"13d6+121","hd_value":13,"fort":11,"ref":12,"will":12,"defensive_abilities":["medium fortification (75%)"],"resists":["electricity 30","fire 15"],"weaknesses":["vulnerable to electricity"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"},{"type":"land","speed":40}],"melee":"staff of mithral might +11 (1d6+5), slam +9 (1d6+3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"change shape","details":"13 rounds/day, beast shape III/elemental body II"}]},{"frequency":"9/day","spells":[{"spell":"telekinetic fist","details":"1d4+6 bludgeoning"}]}],"spellsprepared_caster_level":13,"spellsprepared_concentration":19,"spellsprepared":[{"spell_level":7,"spell_slots":3,"spells":[{"spell":"prismatic spray"},{"spell":"reverse gravity","count":2}]},{"spell_level":6,"spell_slots":5,"spells":[{"spell":"disintegrate","count":2},{"spell":"flesh to stone"},{"spell":"greater dispel magic"},{"spell":"quickened mirror image"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"baleful polymorph","count":2},{"spell":"cone of cold"},{"spell":"dismissal"},{"spell":"quickened shield"},{"spell":"wall of force"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"dimension door","count":2},{"spell":"fear"},{"spell":"mass reduce person","count":2},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"extended false life"},{"spell":"fireball"},{"spell":"fly"},{"spell":"protection from energy"},{"spell":"slow","count":2}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"acid arrow"},{"spell":"cat's grace","count":2},{"spell":"extended mage armor"},{"spell":"glitterdust"},{"spell":"scorching ray","count":3}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"expeditious retreat"},{"spell":"grease"},{"spell":"magic missile","count":3},{"spell":"reduce person","count":2},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"arcane mark"},{"spell":"mage hand"},{"spell":"open/close"},{"spell":"prestidigitation"}]}],"thassilonian_specialization":"transmutation","prohibited_schools":"enchantment, illusion","strength":14,"dexterity":18,"constitution":21,"intelligence":22,"wisdom":15,"charisma":14,"baseatk":6,"cmb":8,"cmd":23,"feats":[{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Rod"},{"feat":"Craft Staff"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Extend Spell"},{"feat":"Greater Spell Focus (transmutation)"},{"feat":"Lightning Reflexes"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (transmutation)"},{"feat":"Toughness"}],"skills":[{"skill":"Appraise","value":23},{"skill":"Craft (metalworking)","value":23},{"skill":"Fly","value":15},{"skill":"Knowledge (arcana, nature, nobility, planes)","value":23},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":16},{"skill":"Spellcraft","value":23},{"skill":"Swim","value":-1}],"languages":["Abyssal","Aklo","Draconic","Giant","Infernal","Terran","Thassilonian"],"sq":["arcane bond (staff)","physical enhancement +3 Con"],"special_abilities":[{"type":"Medium Fortification","kind":"Ex","details":"Whenever a sneak attack or critical hit is scored against Ordikon, there is a 75% chance that the extra damage is negated."},{"type":"Vulnerable to Electricity","kind":"Ex","details":"Ordikon takes 150% normal damage from electricity attacks."}],"gear":"cloak of resistance +1, pearl of power (2nd level), rod of metal and mineral detection, 500 gp in diamond dust, staff of mithral might","before_combat":"Ordikon starts every day by casting extended false life, mage armor, and unseen servant. In the event that he hears combat nearby (or if he hears any of the golems in area G4 activate), he takes the time to cast the following spells before investigating: shield, stoneskin, fly, protection from energy (electricity), cat's grace, and expeditious retreat.","during_combat":"If caught off guard, Ordikon uses dimension door to travel to area G8, casts his short-term defensive spells as outlined above, then returns to G6 to confront the PCs. He always opens by casting disintegrate on any obvious clerics, along with a quickened mirror image.","morale":"Ordikon fights until reduced to 20 hit points or fewer, whereupon he uses dimension door to travel to area G8. If confronted there, he fights to the death.","source":"RotRL-AE-Sins of the Saviors, Advanced Bestiary 169"},{"name":"Eryalla, Lelyrin, Voivod, And Zevashala","cr":10,"xp":9600,"race":"alu-demon submissive 5","gender":"Female","age_category":"Adult","alignment":"CE","size":"Medium","type":"outsider","sub_types":["chaotic","demon","evil","extraplanar"],"init":3,"senses":["darkvision 120 ft."],"ac":23,"ac_touch":14,"ac_flat_footed":19,"ac_mods":"+3 armor, +3 Dex, +1 dodge, +6 natural","hp":124,"hd":"6d10+5d10+66","hd_value":11,"fort":14,"ref":13,"will":10,"save_mods":"+5 vs. sleep and fatigue","defensive_abilities":["beauty of blood","evasion","mock obedience","pain is pleasure","tirelessness"],"dr":"5/cold iron or good","immunities":["electricity","poison"],"resists":["acid 10","cold 10","fire 10"],"sr":16,"speed":[{"type":"fly","speed":50,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"mwk ranseur +19 (2d4+9/x3) or 2 claws +19 (1d6+6 plus vampiric claws)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"shield the mistress"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dimension door"}]},{"frequency":"3/day","spells":[{"spell":"charm person"},{"spell":"detect thoughts"},{"spell":"disguise self"},{"spell":"suggestion"}]}],"strength":22,"dexterity":16,"constitution":21,"intelligence":14,"wisdom":13,"charisma":18,"baseatk":11,"cmb":18,"cmd":34,"feats":[{"feat":"Dodge"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":20},{"skill":"Escape Artist","value":19},{"skill":"Fly","value":19},{"skill":"Knowledge (planes)","value":18},{"skill":"Perception","value":17},{"skill":"Perform (sing)","value":10},{"skill":"Sense Motive","value":17},{"skill":"Stealth","value":19}],"languages":["Abyssal","Celestial","Draconic","telepathy 100 ft."],"sq":["mistress (Delvahine)","mistress said so"],"special_abilities":[{"type":"Beauty of Blood","kind":"Ex","details":"Submissives are immune to bleed damage, and take 1 fewer point of damage from all slashing attacks."},{"type":"Mistress","kind":"Ex","details":"The succubus Delvahine is the mistress to all four of these alu-demon submissives. If any of these alu-demons ever willingly disobeys Delvahine or willingly allows her to come to harm, they lose all of their supernatural abilities save for their vampiric claws, and take a permanent -6 penalty on all saving throws against enchantment effects. If Delvahine dies, these penalties apply as well."},{"type":"Mistress Said So","kind":"Su","details":"The alu-demon submissives gain a +1 morale bonus on all attack rolls, saving throws, skill checks, and ability checks."},{"type":"Mock Obedience","kind":"Su","details":"Any time an alu-demon submissive is affected by a charm or compulsion effect, she may make a second saving throw to break its hold at any time as an immediate action."},{"type":"Pain is Pleasure","kind":"Ex","details":"An alu-demon submissive has damage reduction 5/- against nonlethal damage."},{"type":"Shield the Mistress","kind":"Ex","details":"Whenever Delvahine would be hit by a ranged attack or melee attack and the alu-demon submissive is within 5 ft. of Delvahine, the submissive may make a DC 20 Reflex save to be hit by the attack instead. If Delvahine is forced to make a Reflex save against an effect that normally allows a Reflex save for half damage, the submissive may make that Reflex save against the effect to take the full damage from the effect while preventing any of that damage from harming the mistress. Evasion doesn't protect the submissive from this particular damage. The submissive must be aware of the attack and cannot be flat-footed in order to use this ability. She can attempt to shield the mistress against up to 8 attacks per round."},{"type":"Tirelessness","kind":"Ex","details":"A submissive gains a +5 bonus on saving throws against sleep and fatigue effects."},{"type":"Vampiric Claws","kind":"Su","details":"Each time an alu-demon damages a foe with her claw attack, she gains temporary hit points equal to the amount of damage she inflicted. She cannot gain more hit points in one strike than her target's current hit points + the target's Constitution score (which is enough to kill the target). These temporary hit points vanish in 1 hour."}],"gear":"masterwork ranseur, belt of mighty constitution +2, bracers of armor +3, jewelry worth 8,000 gp","during_combat":"The alu-demons start combat by using suggestion on heavily armored foes, suggesting that those foes take off their armor and gear so the demons can \"get a better look at them.\" They then attempt to use charm person against any foes who resist this initial suggestion. They avoid melee as long as they can, hovering just out of reach of non-flying foes and using their ranseurs. If one alu-demon is forced into melee, the others join their sister, one flanking the foe and the others standing directly behind their sisters to attack with the ranseur via reach so all four can attack one target at a time.","morale":"If reduced to fewer than 50 hit points, an alu-demon uses dimension door to travel to area H7 and takes up a protective position at her mistress's side. If that alu-demon has a charmed PC, she takes that PC with her when she retreats. Delvahine may or may not offer her children and their new pets healing.","source":"RotRL-AE-Sins of the Saviors, Tome of Horrors Complete 154, Plot & Poison 73"},{"name":"Nelevetu Voan","cr":4,"xp":1200,"race":"Azlanti","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":11}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":13,"ac_touch":13,"ac_flat_footed":10,"ac_mods":"+2 Dex, +1 dodge","hp":81,"hd":"11d10+16","hd_value":11,"fort":1,"ref":-3,"will":-6,"save_mods":"+3 vs. fear","defensive_abilities":["bravery +3"],"weaknesses":["energy drained","schizophrenic"],"speed":[{"type":"land","speed":30}],"melee":"unarmed strike +5 (1d3+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"pole arms +2, close +1"}],"strength":17,"dexterity":15,"constitution":18,"intelligence":10,"wisdom":12,"charisma":14,"baseatk":11,"cmb":4,"cmd":17,"feats":[{"feat":"Dodge"},{"feat":"Greater Weapon Focus (halberd)"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (halberd)"},{"feat":"Improved Initiative"},{"feat":"Improved Unarmed Strike"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (halberd)"},{"feat":"Weapon Specialization (halberd)"}],"skills":[{"skill":"Intimidate","value":2},{"skill":"Perception","value":-2},{"skill":"Sense Motive","value":-2}],"languages":["Thassilonian"],"sq":["armor training 3"],"special_abilities":[{"type":"Energy Drained","details":"Nelevetu currently suffers from 10 permanent negative levels, courtesy of encounters with Delvahine. The penalties to his stats and hit points from these negative levels have been calculated into the stats above."},{"type":"Schizophrenic","details":"Nelevetu suffers from madness-specifically, from a potent case of schizophrenia. This debilitating condition makes him take a -4 penalty on all Wisdom- and Charisma-based skill checks. In addition, it prevents him from ever taking 10 or 20 on any roll. In addition, he must make a DC 16 Will save each round he's in a stressful situation (such as combat) to resist becoming confused for 1d6 rounds."}],"during_combat":"If attacked, Nelevetu shrieks and cries, but does his best to fight back to defend himself-although it's more likely he'll become confused due to his schizophrenia. The noise he makes, if outside of his cage, is enough to alert all of the inhabitants of the Iron Cages, who come to investigate at once. If cured of his madness, Nelevetu is grateful and agrees to aid those who saved him in fighting against his oppressors- particularly if they remove his negative levels and give him equipment he can use.","morale":"Nelevetu fights to the death, regardless of the state of his mind and soul-he's not suicidal, but after as long as he's lived, he certainly no longer fears death.","source":"RotRL-AE-Sins of the Saviors"},{"name":"Delvahine","cr":15,"xp":51200,"race":"succubus","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":6},{"class":"dominant","level":5}],"alignment":"CE","size":"Medium","type":"outsider","sub_types":["chaotic","demon","evil","extraplanar"],"init":6,"senses":["darkvision 60 ft.","detect good"],"ac":29,"ac_touch":16,"ac_flat_footed":23,"ac_mods":"+6 armor, +6 Dex, +7 natural","hp":249,"hd":"8d10+11d8+158","hd_value":19,"fort":15,"ref":20,"will":17,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic","dr":"10/cold iron or good","immunities":["electricity","fire","poison"],"resists":["acid 10","cold 10"],"sr":18,"speed":[{"type":"fly","speed":50,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"sadist's lash +22 (1d3+5/19-20), +1 dagger +21 (1d4+5/19-20) or 2 claws +22 (1d4+4 plus 1d3 nonlethal) or agonizing touch +22 (1d3 nonlethal)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"agonizing touch"},{"type":"bardic performance 27 rounds/day","details":"countersong, distraction, fascinate, inspire competence +2, inspire courage +2, suggestion"},{"type":"binding whip"},{"type":"deadly whip"},{"type":"energy drain"},{"type":"penetrating whip"},{"type":"profane gift"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":25,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"tongues"}]},{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"detect thoughts"},{"spell":"ethereal jaunt","details":"self plus 50 lbs. of objects only"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"suggestion"},{"spell":"vampiric touch"}]},{"frequency":"1/day","spells":[{"spell":"dominate person"},{"spell":"summon","details":"1 babau 50%, level 3"}]}],"spellsknown_caster_level":11,"spellsknown_concentration":24,"spellsknown":[{"spell_level":4,"spell_slots":5,"spells":[{"spell":"dominate person"},{"spell":"freedom of movement"},{"spell":"greater invisibility"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"confusion"},{"spell":"dispel magic"},{"spell":"displacement"},{"spell":"haste"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blindness/deafness"},{"spell":"cure moderate wounds"},{"spell":"eagle's splendor"},{"spell":"hold person"},{"spell":"mirror image"}]},{"spell_level":1,"spell_slots":9,"spells":[{"spell":"alarm"},{"spell":"animate rope"},{"spell":"cure light wounds"},{"spell":"grease"},{"spell":"hideous laughter"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":18,"dexterity":23,"constitution":26,"intelligence":16,"wisdom":14,"charisma":36,"baseatk":15,"cmb":19,"cmd":35,"feats":[{"feat":"Arcane Strike"},{"feat":"Combat Reflexes"},{"feat":"Dazzling Display"},{"feat":"Double Slice"},{"feat":"Greater Two-Weapon Fighting"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Spell Focus (enchantment)"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (whip)"}],"skills":[{"skill":"Acrobatics","value":36},{"skill":"Bluff","value":37},{"skill":"Diplomacy","value":36},{"skill":"Escape Artist","value":29},{"skill":"Fly","value":36},{"skill":"Heal","value":11},{"skill":"Intimidate","value":36},{"skill":"Knowledge (arcana, planes)","value":20},{"skill":"Perception","value":33},{"skill":"Perform (dance)","value":36},{"skill":"Perform (oratory)","value":36},{"skill":"Sense Motive","value":36},{"skill":"Stealth","value":29}],"languages":["Abyssal","Celestial","Draconic","Thassilonian","telepathy 100 ft."],"sq":["bardic knowledge +3","change shape (Small or Medium humanoid; alter self)","enchantment specialization","lore master 1/day","versatile performance (dance, oratory)"],"special_abilities":[{"type":"Agonizing Touch","kind":"Su","details":"Delvahine can deal 1d3 points of nonlethal damage with a touch attack at will as a standard action. She deals an additional 1d3 points of nonlethal damage with her natural attacks."},{"type":"Binding Whip","kind":"Ex","details":"Delvahine doesn't provoke attacks of opportunity when she uses a whip in melee. She can also attempt to entangle a Large or smaller foe with a whip-to do so, she makes a touch attack against a target. If she hits, the target is entangled. If she succeeds at an opposed Strength check against the target, the target can not move farther than 15 ft. away from Delvahine. An entangled creature can escape with a successful DC 20 Escape Artist check (a full-round action) or DC 25 Strength check, or by sundering the whip. As long as she entangles a foe with her whip, Delvahine cannot use that whip to make additional attacks. Delvahine can release a foe from her binding whip as an immediate action."},{"type":"Deadly Whip","kind":"Ex","details":"Delvahine can choose to deal normal damage with a whip rather than nonlethal damage."},{"type":"Enchantment Specialization","kind":"Ex","details":"Delvahine gains a +1 bonus to overcome SR when she casts dominate person, and the save DC of any dominate person spell she casts increases by 1."},{"type":"Penetrating Whip","kind":"Su","details":"Delvahine can harm any foe with her whip, regardless of the foe's armor or natural armor bonuses."}],"gear":"+2 glamered mithral chain shirt, sadist's lash, +1 dagger, belt of physical might +4 (Dex, Con)","before_combat":"Delvahine is unlikely to be caught off guard by the PCs since her daughters keep in telepathic contact with her. Once she knows the PCs are approaching (either at her permission or otherwise), she casts freedom of movement, eagle's splendor, and mirror image.","during_combat":"Delvahine prefers to fight with allies, particularly her submissive daughters, who are well trained at protecting her. She uses her bardic performance to inspire courage on the first round of combat, then moves on to use dominate person and confusion against her foes. If forced to fight in melee, she fights with dagger and sadist's lash, using Arcane Strike each round to deal an additional 3 points of damage with each hit.","morale":"Delvahine teleports to area I2 if brought below 20 hit points-as distasteful as it is to her, she hopes to seek aid from Vraxeris. When she discovers he is dead and only his simulacra remains, she assumes his form, allies with his simulacra, and awaits the PCs' arrival in that wing to seek revenge.","source":"RotRL-AE-Sins of the Saviors, Pathfinder RPG Bestiary 68, Plot & Poison 66"},{"name":"False Vraxerise","cr":8,"xp":4800,"race":"Azlanti Human simulacrum","gender":"Male","age_category":"Adult","classes":[{"class":"illusionist","level":9}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":17,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+1 deflection, +2 Dex, +4 shield","hp":93,"hd":"9d6+59","hd_value":9,"fort":9,"ref":8,"will":10,"speed":[{"type":"land","speed":30}],"melee":"mwk dagger +6 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"invisibility field","details":"9 rounds/day"}]},{"frequency":"7/day","spells":[{"spell":"blinding ray"}]}],"spellsprepared_caster_level":9,"spellsprepared_concentration":13,"spellsprepared":[{"spell_level":5,"spell_slots":3,"spells":[{"spell":"feeblemind"},{"spell":"shadow evocation","count":2}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"confusion"},{"spell":"empowered scorching ray"},{"spell":"greater invisibility"},{"spell":"phantasmal killer","count":2}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"dispel magic"},{"spell":"displacement"},{"spell":"extended false life"},{"spell":"fireball"},{"spell":"major image","count":2}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"invisibility","count":2},{"spell":"minor image","count":2},{"spell":"mirror image"},{"spell":"resist energy"},{"spell":"scorching ray"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"charm person"},{"spell":"magic missile","count":2},{"spell":"ray of enfeeblement"},{"spell":"shield"},{"spell":"silent image","count":2}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"prestidigitation"}]}],"prohibited_schools":"conjuration, transmutation","strength":10,"dexterity":14,"constitution":16,"intelligence":19,"wisdom":13,"charisma":16,"baseatk":4,"cmb":5,"cmd":18,"feats":[{"feat":"Combat Casting"},{"feat":"Empower Spell"},{"feat":"Eschew Materials"},{"feat":"Extend Spell"},{"feat":"Greater Spell Focus (illusion)"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (illusion)"},{"feat":"Toughness"}],"skills":[{"skill":"Diplomacy","value":13},{"skill":"Knowledge (arcana, nobility, religion)","value":17},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":11},{"skill":"Spellcraft","value":17}],"languages":["Aklo","Draconic","Giant","Necril","Thassilonian"],"sq":["arcane bond (dagger)","extended illusions +4 rounds"],"gear":"masterwork dagger, ring of protection +1, cloak of resistance +2, headband of vast intelligence +2, noble's outfit worth 200 gp, spellbook (contains only spells prepared)","before_combat":"If the simulacra suspect trouble is coming (such as if they hear combat in area I1), they cast false life, invisibility, and shield on themselves.","during_combat":"The simulacra do their best to rely on invisibility and ranged spells to keep foes from being able to directly engage them with ease.","morale":"The simulacra fight until destroyed.","source":"RotRL-AE-Sins of the Saviors"}];
